"""Original restatements for newly assessed questions whose source rights are reserved."""
import json,pathlib
p=pathlib.Path('research/asia/reviews.json');r=json.loads(p.read_text())
statements={
'ind_2017_f44f99':r'''Fold a square sheet $ABCD$ along a crease meeting $AB$ at $E$ and $CD$ at $F$. The fold sends $A$ to an interior point $A'$ of $BC$ and $D$ to $D'$. Put $G=A'D'\cap CD$. Prove that the inradius of $GCA'$ equals the sum of the inradii of $GD'F$ and $A'BE$.''',
'ind_2017_4d909c':r'''For some integer $n\ge0$, the cubic $x^3+\alpha x+4-2\cdot2016^n$ has three integer roots, counted with multiplicity. Determine the possible real coefficients $\alpha$.''',
'ind_2017_269854':r'''A convex pentagon $ABCDE$ has four angles $\angle A=\angle B=\angle C=\angle D=120^\circ$. Its five side lengths, in an unspecified order, are consecutive integers. Determine the possible sums $AB+BC+CD$.''',
'ind_2017_fe2467':r'''In a right triangle $ABC$ with right angle at $A$ and $AB<AC$, let $D$ be the foot of the altitude to $BC$. Write $P,Q,I$ for the incenters of $ABD,ACD,ABC$, respectively. Establish both $AI\perp PQ$ and $AI=PQ$.''',
'ind_2017_3d1044':r'''For an integer $n\ge1$, set $x=\sum_{k=0}^{\lfloor n/2\rfloor}\binom n{2k}2^{n-2k}3^k$. Prove that a triangle with side lengths $2x-1,2x,2x+1$ exists and has integer area and integer inradius.''',
'ind_2017_1717ae':r'''Three pairwise distinct positive numbers $a,b,c$ satisfy $abc=1$. Show that $\sum_{\rm cyc}a^6/((a-b)(a-c))>15$.''',
'ind_2017_ef8f74':r'''Let $p>5$ be prime with $p\equiv1\pmod4$. Show that one can choose integers $a_0,a_1$ so the recurrence $a_{k+1}=4a_k-5a_{k-1}$, $k\ge1$, never produces a multiple of $p$.''',
'ind_2017_f587bb':r'''An $n\times n$ matrix has nonnegative integer entries and the same integer sum $m$ in every row and every column. Prove that it is a finite sum of permutation matrices, where a permutation matrix has exactly one $1$ in each row and column and zero elsewhere. The empty sum is allowed when $m=0$.''',
'ind_2019_29d03e':r'''In a triangle $ABC$ with $\angle BAC>90^\circ$, choose $D\in BC$ so that $AB$ is tangent at $A$ to the circle through $A,C,D$. Let $E$ be the perpendicular projection of $B$ onto the line $AD$. If $CA=CD$ and $AE=CE$, determine $\angle BCA$.''',
'ind_2019_52e2b0':r'''Starting with a regular pentagon, repeatedly join consecutive side midpoints, producing eleven nested regular pentagons in total. Color their 55 vertices independently red or blue. Prove that four vertices of a single color lie on a circle.''',
'ind_2019_a370ba':r'''For distinct positive integers $m,n$, prove $\sum_{j=0}^2\gcd(m+j,n+j)\le2|m-n|+1$, and characterize every equality case.''',
'ind_2019_1c64a4':r'''If positive integers $M,n$ satisfy $M>n^{n-1}$, prove that the integers $M+1,\ldots,M+n$ admit pairwise distinct prime divisors: choose a prime $p_j\mid M+j$ for each $j$, with all $p_j$ different.''',
'ind_2019_f8a12e':r'''A circle $\Gamma$ has diameter $AB$, and $C$ is another point on it. Let $D$ be the projection of $C$ onto $AB$. Choose $K$ on $CD$ so that the semiperimeter of $ADK$ is $AC$. Prove that the excircle of $ADK$ opposite $A$ is tangent to $\Gamma$.''',
'ind_2019_5478cf':r'''Suppose $f:(\mathbb R\setminus\{0\})^2\to(0,\infty)$ is multiplicative separately in both variables: $f(xy,z)=f(x,z)f(y,z)$ and $f(x,yz)=f(x,y)f(x,z)$ whenever the variables are nonzero. Assume also $f(x,1-x)=1$ for $x\notin\{0,1\}$. Prove $f(x,x)=f(x,-x)=1$ and $f(x,y)f(y,x)=1$ for all nonzero $x,y$.''',
'ind_2020_1d994f':r'''Two circles $\Gamma_1,\Gamma_2$ of different radii meet at $A,B$; each center lies outside the other circle. The tangent to $\Gamma_1$ at $B$ meets $\Gamma_2$ again at $C$, and the tangent to $\Gamma_2$ at $B$ meets $\Gamma_1$ again at $D$. The internal bisectors of $\angle DAB$ and $\angle CAB$ meet $\Gamma_1$ and $\Gamma_2$ again at $X,Y$. If $P,Q$ are the circumcenters of $ACD,XAY$, prove that $PQ$ is the perpendicular bisector of the segment joining the two original centers.''',
'ind_2020_28e27a':r'''A real polynomial $P$ satisfies $P(\cos\theta+\sin\theta)=P(\cos\theta-\sin\theta)$ for every real $\theta$. Prove that $P(x)$ is a polynomial in $(1-x^2)^2$.''',
'ind_2020_9f83b1':r'''Choose a set $S$ of decimal digits so that every nonnegative integer is the sum of two nonnegative integers whose decimal digits all belong to $S$. What is the minimum size of $S$?''',
'ind_2020_b8bee9':r'''Suppose $n\ge3$, $1<a_1\le\cdots\le a_n$, and $\sum_{i=1}^n a_i=2n$. Prove $2+\sum_{k=1}^{n-1}\prod_{i=1}^k a_i\le\prod_{i=1}^n a_i$.''',
'ind_2020_278cd4':r'''Show that sixteen grid-aligned $1\times3$ rectangles cannot cover a $5\times5$ board with each cell covered either once or twice. Every rectangle must stay within the board; horizontal and vertical placements are permitted.''',
'ind_2021_1a427e':r'''Determine the integer pairs $(a,b)$ for which both $x^3+ax+b$ and $x^3+bx+a$ split completely into linear factors over the integers.''',
'ind_2021_4b557b':r'''Take 2021 points in the plane with no three collinear and draw every joining segment. Reveal the midpoints of any 1011 of these segments. Is it always possible to construct the midpoint of any further chosen segment using only an unmarked straightedge? Justify the answer. An allowed step draws the line through two already known distinct points.''',
'ind_2021_3f0960':r'''The labels $1,\ldots,52$ are hidden on 52 cards. A detective may repeatedly choose a pair and ask whether their labels are consecutive, receiving truthful answers. She must eventually name a pair with consecutive labels. Prove that a guaranteed strategy exists with 50 questions, and that no strategy with fewer questions can guarantee success.''',
'ind_2021_8f08e8':r'''A convex quadrilateral $ABCD$ satisfies $CD=CB$, $\angle ABD=30^\circ$, $\angle BCA=75^\circ$, and $\angle ACD=25^\circ$. The ray $CB$ meets the circle through $D,A,C$ again at $E$. Show that $CE=BD$.''',
'ind_2023_182213':r'''A finite set $S$ of positive integers has exactly 2023 ordered pairs $(x,y)\in S^2$ with square product $xy$. Show that $S$ contains four distinct elements for which every product of two different chosen elements is nonsquare.''',
'ind_2023_a65b08':r'''Let $a_0,\ldots,a_{100}>0$, interpreting subscripts modulo 101. For $0\le k\le100$, form $P_k(x)=a_{100+k}x^{100}+100a_{99+k}x^{99}+\sum_{j=0}^{98}a_{j+k}x^j$. Prove that at least one of these 101 polynomials has a nonreal root.''',
'ind_2023_aa198e':r'''Determine all real $c$ for which a function $f:\mathbb Z_{>0}\to\mathbb Z_{>0}$ can satisfy both $|f(x)-cx|<2023$ for every positive $x$ and the following restriction: for positive $x,a$, the quotient $(f(x+a)-f(x))/a$ is an integer exactly when $a=1$.''',
'ind_2023_616c71':r'''Place $2N+1$ coins on a circle, all heads up, where $N>1$. Calvin repeatedly changes one head to a tail. After each such move, Hobbes may change at most one neighboring tail of that coin back to a head. For which positive integers $k$ can Calvin force a position with $k$ tails after Hobbes's turn?''',
'ind_2023_593616':r'''For each distance $d$ between a pair of $n$ distinct planar points, record the unique integer $k$ with $2^k\le d<2^{k+1}$. Prove that fewer than $2n$ different integers are recorded.''',
'ind_2024_0502bc':r'''In an isosceles triangle $ABC$ with $CA=CB$, choose $E$ on its circumcircle such that $CE\perp CB$. The line through $E$ parallel to $CB$ meets $CA$ at $F$ and $AB$ at $G$. Prove that the circumcenter of $EGB$ lies on the circumcircle of $ECF$.''',
'ind_2024_36beb1':r'''Start with a white $2024\times2024$ board. A move chooses an entirely white row or an entirely white column and colors exactly 1000 of its cells red. Determine the largest number of red cells obtainable.''',
'ind_2024_5be055':r'''Let $p$ be an odd prime. If integers $a,b,c$ satisfy $a^{2023}+b^{2023}\equiv b^{2024}+c^{2024}\equiv c^{2025}+a^{2025}\equiv0\pmod p$, show that $a\equiv b\equiv c\equiv0\pmod p$.''',
'ind_2024_29557d':r'''Call a finite set $S$ of positive integers cardinal when $|S|\in S$. A function $f:\mathbb Z_{>0}\to\mathbb Z_{>0}$ has the property that the image $f(S)$ is cardinal whenever $S$ is cardinal. Determine every possible value of $f(2024)$.''',
'ind_2024_989122':r'''Let $A_1,A_2,A_3$ occur counterclockwise on a circle $\Gamma$. For each $i$, let $\tau_i$ be the counterclockwise rotation about $A_i$ through the angle of triangle $A_1A_2A_3$ at that vertex. Given any point $P$, define $P_i=\tau_{i+2}(\tau_i(\tau_{i+1}(P)))$, with subscripts modulo 3. Prove that the circumradius of $P_1P_2P_3$ is at most the radius of $\Gamma$.''',
'ind_2024_3d5780':r'''For integers $n\ge3$, set $A_n=\sum_{j=1}^n\sqrt{n^2+2j-1}$ and $B_n=\sum_{j=1}^n\sqrt{n^2+2j}$. Determine exactly when $\lfloor A_n\rfloor=\lfloor B_n\rfloor$.''',
'chn_2012_d9329f':r'''The incircle of triangle $ABC$, centered at $I$, touches $AB,AC$ at $D,E$. Let $O$ be the circumcenter of $BCI$. Prove $\angle ODB=\angle OEC$.''',
'chn_2012_faca65':r'''The incircle of $ABC$, with center $I$, touches $AB,BC,CA$ at $D,E,F$. The line $EF$ meets $AI,BI,DI$ at $M,N,K$, respectively. Show that $DM\cdot KE=DN\cdot KF$.''',
'chn_2022_bed53a':r'''Positive real sequences satisfy $a_{n+1}=a_n-(1+\sum_{i=1}^n1/a_i)^{-1}$ and $b_{n+1}=b_n+(1+\sum_{i=1}^n1/b_i)^{-1}$ for all $n\ge1$. (a) Assuming $a_{100}b_{100}=a_{101}b_{101}$, determine $a_1-b_1$. (b) Assuming instead $a_{100}=b_{99}$, compare $a_{100}+b_{100}$ with $a_{101}+b_{101}$.''',
'chn_2023_b3eef6':r'''Find the least real $\lambda$ such that every positive integer $n$ admits $n=x_1\cdots x_{2023}$, where each $x_i$ is either prime or a positive integer at most $n^\lambda$.''',
'chn_2023_364475':r'''Determine the greatest constant $C$ such that $\sum_{i,j=1}^n(n-|i-j|)x_ix_j\ge C\sum_{i=1}^n x_i^2$ for every $n\ge1$ and every real tuple $(x_1,\ldots,x_n)$.''',
'chn_2023_ca3b99':r'''In acute triangle $ABC$, take $K$ beyond $C$ on the ray $BC$. Choose $P,Q$ with $BP=BK$, $CQ=CK$, $PK\parallel AB$ and $QK\parallel AC$. Let $T\ne K$ be the second intersection of $AK$ with the circle through $P,Q,K$. Prove $\angle APB+\angle BTC=\angle CQA$ and $AP\cdot BT\cdot CQ=AQ\cdot BP\cdot CT$.'''
}
for id,statement in statements.items():
 r[id]['statementOverride']=statement
 if 'Statement restated independently.' not in r[id].get('note',''):r[id]['note']=(r[id].get('note','')+' Statement restated independently.').strip()
p.write_text(json.dumps(r,ensure_ascii=False,indent=2));print('Restated',len(statements),'questions')
